//! The vehicles that keep their script (M-0103 criterion 2). The list is
//! `docs/dev/ai-response-fallback.txt`: road vehicles whose script's response does not agree with
//! the cheap table model. A listed vehicle runs its script while it is near the camera, and the
//! script's wheel torque and brake force drive it there.

use std::path::Path;

use bevy::prelude::Component;
use opts_scripted_drive::script_accel;

use super::*;

/// The fallback list, compiled in (generated by the AI response census, see its header).
const LIST: &str = include_str!("../../../../../../../docs/dev/ai-response-fallback.txt");

/// Whether `bus_path` names a road vehicle of the fallback list.
#[must_use]
pub fn is_fallback(bus_path: &Path) -> bool {
    let path = normalise(&bus_path.to_string_lossy());
    LIST.lines()
        .filter(|l| !l.trim().is_empty() && !l.starts_with('#'))
        .map(normalise)
        .filter(|l| l.ends_with(".bus"))
        .any(|entry| path.ends_with(&entry))
}

/// Case, slashes and surrounding space do not matter in a path of the list.
fn normalise(s: &str) -> String {
    s.trim().to_ascii_lowercase().replace('\\', "/")
}

/// A listed vehicle: while it is near the camera its script gives its acceleration, from the
/// wheel torque `M_Wheel` and the brake force `Brakeforce` on a vehicle of `mass_kg` (the whole
/// consist) and wheels of `radius_m`. `engaged` is whether the acceleration is currently set.
/// `last_speed` is the speed (m/s) at the previous frame the vehicle was visited, for the speed
/// jump at a LOD switch (`lod switch` log line; `None` before the first frame).
#[derive(Component, Debug, Clone, Copy)]
pub struct ScriptDrive {
    pub mass_kg: f64,
    pub radius_m: f64,
    pub engaged: bool,
    pub last_speed: Option<f64>,
}

/// The components a vehicle with scripts is queried by: the script, its route and its drive.
pub(super) type ScriptedVehicle = (
    &'static TrafficVehicle,
    &'static mut VehicleScripts,
    &'static mut VehicleRoute,
    &'static mut AiScript,
    &'static opts_bevy::AiVariables,
    Option<&'static mut ScriptDrive>,
);

/// Sets the vehicle's acceleration from its script's `M_Wheel` and `Brakeforce` (the script ran
/// this frame); without a readable engine the car-following law drives it.
pub(super) fn apply_script_drive(
    world: &mut opts_traffic::TrafficWorld,
    id: opts_traffic::AgentId,
    scripts: &mut VehicleScripts,
    drive: &mut ScriptDrive,
    speed: f64,
) {
    let was = drive.engaged;
    let acc = scripts.engine.get_mut().ok().map(|engine| {
        script_accel(
            f64::from(engine.get("M_Wheel")),
            f64::from(engine.get("Brakeforce")),
            drive.mass_kg,
            drive.radius_m,
        )
    });
    world.set_external_accel(id, acc);
    drive.engaged = acc.is_some();
    if !was && drive.engaged {
        tracing::info!(
            agent = id.0,
            speed_ms = speed,
            "listed vehicle drives from its script"
        );
    }
    if was != drive.engaged {
        let to = if drive.engaged { "script" } else { "kinematic" };
        log_lod_switch(id, to, drive.last_speed, speed);
    }
    drive.last_speed = Some(speed);
}

/// Gives the vehicle back to the car-following law (it left the script's reach).
pub(super) fn release_script_drive(
    world: &mut opts_traffic::TrafficWorld,
    id: opts_traffic::AgentId,
    drive: &mut ScriptDrive,
    speed: f64,
) {
    if drive.engaged {
        world.set_external_accel(id, None);
        drive.engaged = false;
        log_lod_switch(id, "kinematic", drive.last_speed, speed);
    }
    drive.last_speed = Some(speed);
}

/// Logs a LOD switch (`lod switch`) with the speed of the previous frame (`v_before_mps`), of the
/// switch frame (`v_now_mps`) and their difference (`jump_mps`, m/s). Criterion 1 holds when
/// `|jump_mps|` stays at or below 0.3. `to` is the driver after the switch. Without a previous
/// frame the fields are NaN.
fn log_lod_switch(id: opts_traffic::AgentId, to: &'static str, before: Option<f64>, now: f64) {
    let before = before.unwrap_or(f64::NAN);
    tracing::debug!(
        agent = id.0,
        to,
        v_before_mps = before,
        v_now_mps = now,
        jump_mps = now - before,
        "lod switch"
    );
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use super::is_fallback;

    #[test]
    fn listed_road_vehicles_match_whatever_their_case_or_slashes() {
        assert!(is_fallback(Path::new(
            "/omsi/Vehicles/TH_MB_SK/TH_MB_SK_Pritsche.bus"
        )));
        assert!(is_fallback(Path::new(
            "/omsi/vehicles/th_mb_sk/th_mb_sk_pritsche.bus"
        )));
        assert!(!is_fallback(Path::new(
            "/omsi/Vehicles/DAF_XF_105/DAF_XF_105.bus"
        )));
        // Trams and trains are not road vehicles and keep the table.
        assert!(!is_fallback(Path::new(
            "/omsi/Vehicles/HH109_U-Bahn DT4/DT4.ovh"
        )));
    }
}
